/**
 * The bundled equipment and exercise catalogue (generated by scripts/build_catalogue.py).
 */
import equipmentData from '../../assets/catalogue/equipment.json';
import exerciseData from '../../assets/catalogue/exercises.json';

import type { MuscleGroup, TargetKind } from '@/domain/types';

import { exerciseImages } from './images.generated';

export type EquipmentCategory = 'free_weights' | 'benches_racks' | 'machines' | 'cardio';
export type ExerciseCategory = 'strength' | 'plyometric' | 'cardio';

export interface Equipment {
  id: string;
  name: string;
  category: EquipmentCategory;
  imageExerciseId: string;
}

export interface EquipmentPreset {
  id: string;
  name: string;
  equipmentIds: string[];
}

export interface Exercise {
  id: string;
  name: string;
  category: ExerciseCategory;
  level: string;
  mechanic: string | null;
  primaryMuscles: MuscleGroup[];
  secondaryMuscles: MuscleGroup[];
  /** Every item listed is required. Empty means bodyweight only. */
  equipment: string[];
  defaultTarget: TargetKind;
  instructions: string[];
}

export const EQUIPMENT_CATEGORY_LABELS: Record<EquipmentCategory, string> = {
  free_weights: 'Free weights',
  benches_racks: 'Benches and racks',
  machines: 'Machines',
  cardio: 'Cardio',
};

export const equipment = equipmentData.equipment as Equipment[];
export const equipmentPresets = equipmentData.presets as EquipmentPreset[];
export const exercises = exerciseData.exercises as unknown as Exercise[];

const exerciseById = new Map(exercises.map((e) => [e.id, e]));
const equipmentById = new Map(equipment.map((e) => [e.id, e]));

export function getExercise(id: string): Exercise | undefined {
  return exerciseById.get(id);
}

export function getEquipment(id: string): Equipment | undefined {
  return equipmentById.get(id);
}

/** Image module for an exercise, for <Image source={...} />. */
export function exerciseImage(id: string): number | undefined {
  return exerciseImages[id];
}

export function equipmentImage(id: string): number | undefined {
  const item = equipmentById.get(id);
  return item ? exerciseImages[item.imageExerciseId] : undefined;
}

/** True when the user owns every piece of equipment the exercise needs. */
export function isAvailable(exercise: Exercise, ownedEquipmentIds: readonly string[]): boolean {
  return exercise.equipment.every((id) => ownedEquipmentIds.includes(id));
}

export interface ExerciseFilter {
  equipmentIds: readonly string[];
  muscle?: MuscleGroup | null;
  query?: string;
}

/** Exercises the user can do, optionally narrowed by muscle group and a name search. */
export function filterExercises({ equipmentIds, muscle, query }: ExerciseFilter): Exercise[] {
  const q = query?.trim().toLowerCase() ?? '';
  return exercises
    .filter((e) => isAvailable(e, equipmentIds))
    .filter((e) => !muscle || e.primaryMuscles.includes(muscle))
    .filter((e) => !q || e.name.toLowerCase().includes(q))
    .sort((a, b) => a.name.localeCompare(b.name));
}
